from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[1]
records=[]
def add(key,authors,title,year,venue,url,version,locator,problem,objective,reward,algorithm,market,metric,result,studies,time,benchmark,relation):
 records.append(dict(key=key,authors=authors,title=title,year=year,venue=venue,url=url,version=version,locator=locator,problem=problem,objective=objective,reward=reward,algorithm=algorithm,market=market,metric=metric,result=result,studies_reward_objective=studies,time_inconsistency=time,known_benchmark=benchmark,project_relation=relation))
add('lesmana2025','Nixie Sapphira Lesmana; Chi Seng Pun','A Subgame Perfect Equilibrium Reinforcement Learning Approach to Time-Inconsistent Problems',2025,'SIAM Journal on Financial Mathematics 16(1), 68–122','https://doi.org/10.1137/23M1594510','Journal metadata/abstract verified. Targeted full-text reading of arXiv:2110.14295v1 (27 October 2021), NOT the 2025 final text; saved filename lesmana2025.pdf denotes citation year, not file version.','Read preprint §§3.2.2,4.1–4.4,5.4–6; Algorithm 5 (p.47), Theorems 26–27 (pp.21–22); Figs.1–4 discussed in §5.4.','Time-inconsistent sequential decisions.','Subgame-perfect equilibrium; illustrative terminal mean–variance.','Adjusted action values and auxiliary moment functions.','BPI; tabular Q-learning and deterministic actor–critic. Final abstract calls it EBPI.','Preprint: simulated risky/riskless market, annual mean ±20%, volatility30%, 100 steps.','Policy/critic convergence and terminal mean/standard deviation.','Preprint §5.4 reports policy approach to the known benchmark; critics initialised near true parameters.','Yes.','Explicitly.','Analytical policy in preprint §5.4.2.','Backward equilibrium learning is prior art. Our learner is a structured adaptation, not a published-algorithm reproduction. Candidate addition is a finite-iterate deviation certificate; final-version overlap still needs checking.')
add('guo2026','Xin Guo; Yijie Huang; Xiang Yu','Deterministic Policy Gradient for Learning Equilibrium in Time-Inconsistent Control Problems',2026,'arXiv preprint 2606.11798v1','https://arxiv.org/abs/2606.11798','10 June 2026, 40-page primary PDF. Targeted reading, not full-proof verification.','Read §§1–2, Theorem4.2 statement and proof opening, §5 Algorithms1–3, §6.1 including Eqs.(6.1)–(6.6) and Figs.1–4 discussion.','Continuous-time time-inconsistent control.','Deterministic equilibrium; terminal MV and non-exponential tracking.','Auxiliary-function-dependent modified running reward.','DPG with inner fixed-point iterations and martingale critic learning.','Synthetic financial diffusions; MV example uses one risky asset.','Relative policy/value error and learning stability.','Inner fixed-point convergence theorem; reported MV learning comparisons with entropy-regularised q-learning.','Yes: two-stage reward reformulation.','Explicitly.','Analytical MV equilibrium, Proposition6.1.','Rules out novelty in merely learning auxiliary rewards or using DPG for equilibrium. Our proposed audit concerns finite-iterate discrete-state deviation gains, not their general continuous-time method.')
add('sangadi2025','Tejaram Sangadi; Prashanth L.A.; Krishna Jagannathan','A Finite-Sample Analysis of an Actor-Critic Algorithm for Mean-Variance Optimization in a Discounted MDP',2025,'arXiv:2406.07892v2; publication venue not used without final-version concordance','https://arxiv.org/abs/2406.07892','12 March 2025, 49-page primary preprint. Targeted reading.','Read abstract, §§3–5 theorem statements, Algorithm2, Eq.(15), Theorem4.3 and Assumption8; detailed appendix proofs not fully checked.','Risk-sensitive discounted MDP learning.','Mean minus penalised variance of discounted return from an initial state.','MDP rewards with a return-level variance objective.','Tail-averaged linear TD critic, SPSA actor.','Theoretical finite-state/action discounted MDP; no financial dataset in the inspected analysis.','Critic estimation bounds and expected squared policy-gradient norm.','Theorem4.3 gives O(n^(-1/4)) actor-iteration stationarity bound under stated assumptions.','Yes: distinguishes return variance from reward volatility.','Not a subgame-equilibrium target.','Theoretical stationarity reference; not a portfolio benchmark.','Finite-sample MV actor–critic guarantees already exist. Our audit seeks per-state one-step equilibrium deviation, a different certificate, not a better general convergence rate.')
add('chen2025seminorm','Zaiwei Chen; Sheng Zhang; Zhe Zhang; Shaan Ul Haque; Siva Theja Maguluri','A Non-Asymptotic Theory of Seminorm Lyapunov Stability: From Deterministic to Stochastic Iterative Algorithms',2025,'arXiv preprint 2502.14208v1','https://arxiv.org/abs/2502.14208','20 February 2025, 59-page primary PDF. Targeted reading of introduction, §2 and opening §5.','§2.1 Proposition2.1 and Lemma2.1, §2.2 Theorem2.1, §5.2 Eq.(17).','Seminorm-contractive stochastic approximation and average-reward RL.','General fixed points and average reward, not financial MV.','Generic average-reward MDP.','Seminorm stability theory, TD and Q-learning applications.','Theoretical models.','Seminorm error and finite-sample convergence.','Establishes fixed-point/convergence results allowing irrelevant kernel components.','Analyses value-learning geometry.','Not the financial subgame-equilibrium problem.','Fixed-point solution classes.','Constant-shift invariance, quotient critics and seminorm learning are prior art. Candidate contribution is their specific link to MV deviation gain; no claim to invent centring.')
add('maurer2009','Andreas Maurer; Massimiliano Pontil','Empirical Bernstein Bounds and Sample Variance Penalization',2009,'Proceedings of COLT 2009','https://www.cs.mcgill.ca/~colt2009/papers/012.pdf','9-page conference PDF; targeted reading of §1 and Theorem4.','§1.1 Theorem4, PDF p.2.','Data-dependent concentration and learning.','Statistical risk estimation/variance penalisation.','Not an RL reward.','Empirical Bernstein bounds and sample variance penalisation.','General bounded independent data.','Confidence bounds and excess risk.','Theorem4 provides a sample-variance-dependent confidence radius.','Not applicable.','Not applicable.','Known population expectation in theoretical analysis.','We use Theorem4, p.2, on both tails of fixed-policy audit quantities; the concentration inequality is not ours.')
add('schulman2017','John Schulman; Filip Wolski; Prafulla Dhariwal; Alec Radford; Oleg Klimov','Proximal Policy Optimization Algorithms',2017,'arXiv:1707.06347v2','https://arxiv.org/abs/1707.06347','28 August 2017, 12-page primary preprint. Targeted reading of Sections 1–3, 5 and 6.1; not a claim to have reproduced its full experimental suite.','Eq. (7), Section 5 / Algorithm 1 (p.5), Section 6.1 / Table 1 (p.6).','Stable policy improvement with repeated minibatch updates.','Expected cumulative task reward; not a portfolio objective.','Environment rewards; clipped likelihood-ratio surrogate for policy optimisation.','PPO with clipped objective, actor–critic and GAE.','MuJoCo continuous-control tasks and Atari; no financial data.','Normalised cumulative task reward and learning curves.','Section 6.1 Table 1: clipping at 0.2 scores 0.82 versus -0.39 without clipping or penalty on its normalised benchmark; these are external reported values, not our results.','Studies policy-optimisation surrogates, not whether a financial reward implements terminal MV.','No financial equilibrium analysis.','Task/environment baselines, not closed-form portfolio policies.','A standard optimiser used in a matched reward intervention. SB3 implementation and sample-only continuation refresh are disclosed. We do not replicate the original nonfinancial tasks, claim to improve PPO generally, or equate its compute budget with the direct-gradient learner.')
folder=root/'literature/rl-extension-2026';(folder/'records.json').write_text(json.dumps(records,indent=2,ensure_ascii=False))
old=json.loads((root/'literature/ledger.json').read_text());keys={x['key'] for x in records};rows=[x for x in old if x['key'] not in keys]+records
(root/'literature/ledger.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False))
head='# Primary-paper comparison ledger\n\nUpdated 9 October 2026: '+str(len(rows))+' records. Versions and reading coverage are explicit. External reported results are not replications. RL extension is preliminary and separate from the frozen IAFM manuscript.\n\n| ID | Verified citation | Access / version | Relation |\n|---|---|---|---|\n'
for r in rows:head+=f"| {r['key']} | {r['authors']} ({r['year']}). [{r['title']}]({r['url']}). {r['venue']}. | {r['version']} | {r['project_relation']} |\n"
for r in rows:
 head+='\n## '+r['key']+'\n\n| Field | Extraction |\n|---|---|\n'
 for k in ['locator','problem','objective','reward','algorithm','market','metric','result','studies_reward_objective','time_inconsistency','known_benchmark','project_relation']:head+=f"| {k} | {r[k]} |\n"
(root/'literature/LITERATURE_LEDGER.md').write_text(head)
manifest=[]
for p in folder.glob('*.pdf'):manifest.append(dict(file=p.name,sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
(folder/'manifest.json').write_text(json.dumps(manifest,indent=2))
print(len(rows),'records')
